files.lookup.py:
"""Ordered-sequence lookup helpers."""


def index_of(items, target):
    """Index of the FIRST occurrence of `target` in ascending `items`, or -1 if absent."""
    lo, hi = 0, len(items) - 1
    result = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            result = mid
            hi = mid - 1  # keep searching left for an earlier occurrence
        elif items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return result

