files.chunker.py:
"""Batching helpers."""


def chunk(items, size):
    """Split `items` into consecutive lists of at most `size` items."""
    if size <= 0:
        raise ValueError("size must be positive")
    out = []
    buf = []
    for it in items:
        buf.append(it)
        if len(buf) == size:
            out.append(buf)
            buf = []
    if buf:
        out.append(buf)
    return out

