files.amount.py:
"""Money parsing."""


def parse_amount(text):
    """Parse a money string such as '1,234.50' into a float."""
    if not text.strip():
        return 0.0
    try:
        return float(text.replace(",", ""))
    except (ValueError, TypeError):
        raise ValueError(f"Invalid amount: {text!r}")

"""Money parsing."""


def parse_amount(text):
    """Parse a money string such as '1,234.50' into a float.

    An empty or whitespace-only string means 'no value' and returns 0.0;
    any other text that is not a number raises ValueError.
    """
    if not text or not text.strip():
        return 0.0
    try:
        return float(text.replace(",", ""))
    except Exception:
        raise ValueError(f"not a valid amount: {text!r}")

