files.divisors.py:
"""Number theory helpers."""


def divisors(n):
    """Every positive divisor of `n`, ascending."""
    if n < 1:
        raise ValueError("n must be >= 1")
    small = []
    large = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            small.append(i)
            if i != n // i:
                large.append(n // i)
        i += 1
    return small + large[::-1]

"""Number theory helpers."""


