    """Every positive divisor of `n`, ascending."""
    if n < 1:
        raise ValueError("n must be >= 1")
    small = []
    large = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            small.append(i)
            if i * i != n:
                large.append(n // i)
        i += 1
    return small + large[::-1]

files.freq.py:
"""Frequency helpers."""


def most_common(items):
    """The most frequent item; ties go to whichever appeared first in `items`."""
    counts = {}
    first_seen = {}
    for index, it in enumerate(items):
        counts[it] = counts.get(it, 0) + 1
        first_seen.setdefault(it, index)
    if not counts:
        raise ValueError("items must not be empty")
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], first_seen[kv[0]]))
    return ranked[0][0]

"""Frequency helpers."""


def most_common(items):
    """The most frequent item; ties go to whichever appeared first in `items`."""
    if not items:
        raise ValueError("items must not be empty")
    counts = {}
    first_seen = {}
    for index, it in enumerate(items):
        if it not in counts:
            first_seen[it] = index
        counts[it] = counts.get(it, 0) + 1
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], first_seen[kv[0]]))
    return ranked[0][0]

files.paging.py:
"""Pagination helpers."""


def page_count(total, per_page):
    """How many pages `total` items need."""
    if per_page <= 0:
        raise ValueError("per_page must be positive")
    return (total + per_page - 1) // per_page


def page_items(items, number, per_page):
    """The slice of `items` shown on page `number`. Pages are numbered from 1."""
    if number < 1:
        return []
    start = (number - 1) * per_page
    return items[start:start + per_page]

